  beforeEach(() => {
    localStorage.clear();
    vi.stubGlobal(
      "fetch",
      vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => route(input, init)),
    );
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

